# Prints the ceiling of X divided by 10, also for negative X
x = int(input())
if x % 10 == 0:
  print(x // 10)
else:
  print((x + 9) // 10)

# Multiples of 10 are printed unchanged; other values are divided by 10 and rounded up
x = int(input())
if x % 10 == 0:
  print(x)
else:
  print((x + 9) // 10 if x > 0 else (x - 9) // 10)

